+#[cfg(test)]
+mod tests {
+    use super::validate_inline_hidden_states;
+    use serde_json::json;
+    use std::collections::HashMap;
+
+    #[test]
+    fn inline_hidden_states_validate_effective_metadata() {
+        for (params, valid) in [
+            (json!({"return_last_hidden_state": true}), true),
+            (json!({"return_last_hidden_state": "true"}), false),
+            (json!({"return_last_hidden_state": null}), false),
+            (
+                json!({"return_last_hidden_state": true, "include_output_tokens": true}),
+                false,
+            ),
+            (
+                json!({"return_last_hidden_state": true, "hidden_states_path": null}),
+                false,
+            ),
+            (
+                json!({"return_last_hidden_state": true, "include_output_tokens": false}),
+                true,
+            ),
+        ] {
+            let xargs = HashMap::from([("kv_transfer_params".to_string(), params.clone())]);
+            let top = serde_json::from_value(params).unwrap();
+            assert_eq!(
+                validate_inline_hidden_states(None, Some(&xargs)).is_ok(),
+                valid
+            );
+            assert_eq!(
+                validate_inline_hidden_states(Some(&top), None).is_ok(),
+                valid
+            );
+            assert_eq!(
+                validate_inline_hidden_states(Some(&HashMap::new()), Some(&xargs)).unwrap(),
+                false
+            );
+        }
+    }
+}

